 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    def diagonal_groups(sign):
        # sign=-1: key c-r; sign=+1: key c+r
        groups = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    k = c + sign * r
                    groups.setdefault(k, []).append(v)
        consistent = sum(len(vs) for vs in groups.values() if len(set(vs)) == 1)
        conflicts = sum(len(vs) for vs in groups.values() if len(set(vs)) > 1)
        repeated = sum(len(vs) for vs in groups.values() if len(vs) > 1)
        return groups, (consistent, repeated, -conflicts)

    minus = diagonal_groups(-1)
    plus = diagonal_groups(1)
    groups, _ = max((minus, plus), key=lambda item: item[1])

    # Find the shortest repeating stripe period compatible with every
    # observed colored diagonal. The examples encode each phase via seeds.
    keys = list(groups)
    period = 1
    for p in range(1, max(h, w) * 2 + 1):
        phases = {}
        valid = True
        for k, vals in groups.items():
            color = vals[0]
            phase = k % p
            if phase in phases and phases[phase] != color:
                valid = False
                break
            phases[phase] = color
        if valid:
            period = p
            break

    phases = {k % period: vals[0] for k, vals in groups.items()}
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            k = c - r if groups is minus[0] else c + r
            row.append(phases[k % period])
        out.append(row)
    return out

if __name__ == "__main__":
    # Small completion example.
    assert transform([[8, 7], [7, 0]]) == [[8, 7], [7, 8]]
    # Examples are exercised in the development harness.
